'use client';

import { useState } from 'react';
import { GripVertical, Play, Trash2 } from 'lucide-react';
import { usePlayback } from '@/context/PlaybackContext';

const sampleTracks = [
  {
    id: 'pl-1',
    title: 'Relax and Unwind',
    artist: 'Rozé',
    cover: '/AFRO.jpg',
    url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
  },
  {
    id: 'pl-2',
    title: 'Vibe Mix',
    artist: 'Yemi Sax',
    cover: '/AFRO.jpg',
    url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
  },
  {
    id: 'pl-3',
    title: 'Cool Session',
    artist: 'Dunsin',
    cover: '/AFRO.jpg',
    url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-3.mp3',
  },
];

const Playlist = () => {
  const { playTrack, currentIndex, playlist, isPlaying } = usePlayback();
  const [tracks, setTracks] = useState(sampleTracks);
  const [draggedTrackId, setDraggedTrackId] = useState<string | null>(null);

  const handleDrop = (targetTrackId: string) => {
    if (!draggedTrackId || draggedTrackId === targetTrackId) {
      setDraggedTrackId(null);
      return;
    }

    setTracks((currentTracks) => {
      const draggedIndex = currentTracks.findIndex((track) => track.id === draggedTrackId);
      const targetIndex = currentTracks.findIndex((track) => track.id === targetTrackId);

      if (draggedIndex < 0 || targetIndex < 0) return currentTracks;

      const reorderedTracks = [...currentTracks];
      const [draggedTrack] = reorderedTracks.splice(draggedIndex, 1);
      reorderedTracks.splice(targetIndex, 0, draggedTrack);
      return reorderedTracks;
    });

    setDraggedTrackId(null);
  };

  const handleRemove = (trackId: string) => {
    setTracks((currentTracks) => currentTracks.filter((track) => track.id !== trackId));
  };

  return (
    <div className="font-inter">
      <p className="text-xs font-medium text-left text-white mb-2">My Playlist</p>

      <div className="bg-gradient-to-r from-[#6E0596] to-[#580577] p-8 py-12 rounded-lg text-white flex items-center justify-between mb-6">
        <div className="flex-1 gap-2">
          <h1 className="md:text-6xl text-3xl mb-2 font-extrabold">My Playlist</h1>
          <p className="font-semibold text-base">
            {tracks.length} {tracks.length === 1 ? 'Song' : 'Songs'} Added
          </p>
        </div>
      </div>

      {tracks.length === 0 ? (
        <div className="rounded-lg border border-border-dark p-8 text-center text-on-muted">
          Your playlist is empty.
        </div>
      ) : (
        <div aria-label="Playlist tracks" className="flex flex-col gap-2">
          {tracks.map((track, i) => {
            const globalIndex = playlist.findIndex((playlistTrack) => playlistTrack.url === track.url);
            const isActive = globalIndex >= 0 && globalIndex === currentIndex && isPlaying;

            return (
              <div
                key={track.id}
                draggable
                className={`flex items-center gap-4 p-3 rounded-lg transition-colors ${
                  isActive ? 'bg-surface border border-border-dark' : 'hover:bg-surface-hover'
                } ${draggedTrackId === track.id ? 'opacity-50' : ''}`}
                onDragEnd={() => setDraggedTrackId(null)}
                onDragOver={(event) => event.preventDefault()}
                onDragStart={() => setDraggedTrackId(track.id)}
                onDrop={() => handleDrop(track.id)}
              >
                <button
                  aria-label={`Reorder ${track.title}`}
                  className="cursor-grab text-on-muted hover:text-white touch-none"
                  title="Drag to reorder"
                  type="button"
                >
                  <GripVertical size={20} />
                </button>

                <button
                  aria-label={`Play ${track.title}`}
                  className="flex flex-1 min-w-0 items-center gap-4 text-left cursor-pointer"
                  type="button"
                  onClick={() => playTrack(track)}
                >
                  <span className="flex items-center justify-center w-8 h-8 rounded-full bg-brand shrink-0">
                    <Play className="text-white ml-0.5" size={14} />
                  </span>
                  <span className="flex-1 min-w-0">
                    <span
                      className={`block text-sm font-semibold truncate ${
                        isActive ? 'text-brand' : 'text-white'
                      }`}
                    >
                      {track.title}
                    </span>
                    <span className="block text-xs text-on-muted truncate">{track.artist}</span>
                  </span>
                </button>

                <span className="text-xs text-on-muted shrink-0">{i + 1}</span>

                <button
                  aria-label={`Remove ${track.title} from playlist`}
                  className="p-2 rounded-md text-on-muted hover:text-red-400 hover:bg-red-400/10 transition-colors"
                  title="Remove from playlist"
                  type="button"
                  onClick={() => handleRemove(track.id)}
                >
                  <Trash2 size={17} />
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default Playlist;

'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import AvatarCrop from '@/components/common/dashboard/AvatarCrop';

const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
const MAX_SIZE_MB = 5;

const MAX_SIZE_MB = 5;
const MAX_DISPLAY_NAME = 50;
const MAX_BIO = 500;

import { useFormState } from '@/hooks/useFormState';
import { useGetProfile, useUpdateProfile } from '@/hooks/useProfile';



const EditProfile = () => {
  const router = useRouter();
  const { data: profile, isLoading } = useGetProfile();
  const { mutate: update, isPending } = useUpdateProfile();

  const {
    values,
    setValues,
    handleChange,
    handleBlur,
    errors,
    isFormValid,
    fieldError,
    setAllTouched
  } = useFormState({
    displayName: '',
    bio: '',
    website: '',
    twitter: ''
  });

  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [cropOpen, setCropOpen] = useState(false);
  const [rawImageSrc, setRawImageSrc] = useState<string>('');
  const [isDirty, setIsDirty] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (profile) {
      setValues({
        displayName: profile.name || profile.username || '',
        bio: profile.bio || '',
        website: profile.website || '',
        twitter: profile.twitter || '',
      });
    }
  }, [profile]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!ALLOWED_TYPES.includes(file.type)) {
      toast.error('Please select a valid image file (JPEG, PNG, WebP, or GIF).');
      return;
    }

    if (file.size > MAX_SIZE_MB * 1024 * 1024) {
      toast.error(`Image must be under ${MAX_SIZE_MB}MB.`);
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setRawImageSrc(reader.result as string);
      setCropOpen(true);
    };
    reader.readAsDataURL(file);

    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleCropComplete = (croppedDataUrl: string) => {
    setAvatarPreview(croppedDataUrl);
  };



  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Mark all fields as touched so errors show on submit attempt
    setAllTouched();
    if (!isFormValid) return;
    update(
      { name: values.displayName, bio: values.bio, website: values.website, twitter: values.twitter },
      {
        onSuccess: () => {
          setIsDirty(false);
          router.push('/dashboard/profile');
        },
      }
    );
  };

  const handleBack = () => {
    router.push('/dashboard/profile');
  };



  return (
    <div className="min-h-screen">
      <div className="mb-4">
        <button
          className="bg-pink-600 cursor-pointer font-semibold text-xs px-4 py-3 rounded-lg"
          onClick={handleBack}
        >
          Profile
        </button>
      </div>

      {isLoading ? (
        <div className="animate-pulse space-y-4">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="h-12 bg-gray-800 rounded-lg w-full max-w-lg" />
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-30">
          <form noValidate className="lg:col-span-2 space-y-6" onSubmit={handleSubmit}>
            {/* Display Name */}
            <div>
              <label className="block mb-2 text-base font-medium">
                Display name <span className="text-pink-500">*</span>
              </label>
              <input
                aria-describedby={fieldError('displayName') ? 'displayName-error' : undefined}
                aria-invalid={!!fieldError('displayName')}
                className={`w-full bg-[#1A1A1A] text-white rounded-lg px-4 py-2 placeholder:text-sm placeholder:text-[#4B4B4B] focus:outline-none ${
                  fieldError('displayName') ? 'ring-1 ring-red-500' : ''
                }`}
                maxLength={MAX_DISPLAY_NAME + 1}
                placeholder="Add Display name"
                type="text"
                value={values.displayName}
                onBlur={() => handleBlur('displayName')}
                onChange={(e) => handleChange('displayName', e.target.value)}
              />
              <div className="flex justify-between mt-1">
                {fieldError('displayName') ? (
                  <p className="text-red-400 text-xs" id="displayName-error">
                    {fieldError('displayName')}
                  </p>
                ) : (
                  <span />
                )}
                <span className="text-xs text-gray-500 ml-auto">
                  {values.displayName.length}/{MAX_DISPLAY_NAME}
                </span>
              </div>
            </div>

            {/* Bio */}
            <div>
              <label className="block mb-2 text-base font-medium">Short bio</label>
              <input
                aria-describedby={fieldError('bio') ? 'bio-error' : undefined}
                aria-invalid={!!fieldError('bio')}
                className={`w-full bg-[#1A1A1A] text-white rounded-lg px-4 py-2 placeholder:text-sm placeholder:text-[#4B4B4B] focus:outline-none ${
                  fieldError('bio') ? 'ring-1 ring-red-500' : ''
                }`}
                maxLength={MAX_BIO + 1}
                placeholder="Tell about yourself in a few words"
                type="text"
                value={values.bio}
                onBlur={() => handleBlur('bio')}
                onChange={(e) => handleChange('bio', e.target.value)}
              />
              <div className="flex justify-between mt-1">
                {fieldError('bio') ? (
                  <p className="text-red-400 text-xs" id="bio-error">
                    {fieldError('bio')}
                  </p>
                ) : (
                  <span />
                )}
                <span className="text-xs text-gray-500 ml-auto">
                  {values.bio.length}/{MAX_BIO}
                </span>
              </div>
            </div>

            {/* Website */}
            <div>
              <label className="block mb-2 text-base font-medium">Website URL</label>
              <input
                aria-describedby={fieldError('website') ? 'website-error' : undefined}
                aria-invalid={!!fieldError('website')}
                className={`w-full bg-[#1A1A1A] text-white rounded-lg px-4 py-2 placeholder:text-sm placeholder:text-[#4B4B4B] focus:outline-none ${
                  fieldError('website') ? 'ring-1 ring-red-500' : ''
                }`}
                placeholder="https://"
                type="url"
                value={values.website}
                onBlur={() => handleBlur('website')}
                onChange={(e) => handleChange('website', e.target.value)}
              />
              {fieldError('website') && (
                <p className="text-red-400 text-xs mt-1" id="website-error">
                  {fieldError('website')}
                </p>
              )}
            </div>

            {/* Twitter / X */}
            <div>
              <label className="block mb-2 text-base font-medium">X (Twitter)</label>
              <input
                aria-describedby={fieldError('twitter') ? 'twitter-error' : undefined}
                aria-invalid={!!fieldError('twitter')}
                className={`w-full bg-[#1A1A1A] text-white rounded-lg px-4 py-2 placeholder:text-sm placeholder:text-[#4B4B4B] focus:outline-none ${
                  fieldError('twitter') ? 'ring-1 ring-red-500' : ''
                }`}
                placeholder="Enter your X username"
                type="text"
                value={values.twitter}
                onBlur={() => handleBlur('twitter')}
                onChange={(e) => handleChange('twitter', e.target.value)}
              />
              {fieldError('twitter') && (
                <p className="text-red-400 text-xs mt-1" id="twitter-error">
                  {fieldError('twitter')}
                </p>
              )}
            </div>

            <button
              className="bg-pink-600 text-white px-6 py-2 rounded-md font-semibold disabled:opacity-50 disabled:cursor-not-allowed"
              disabled={isPending || !isFormValid}
              type="submit"
            >
              {isPending ? 'Saving…' : 'Save'}
            </button>
          </form>

          <div className="bg-[#1A1A1A] h-85 rounded-xl shadow-md p-3 flex flex-col max-w-xs">
            <Image
              alt="User Profile"
              className="rounded-lg mb-4 object-cover w-full h-40"
              height={200}
              src={avatarPreview || profile?.profileImage || '/dashboard/profiledefault.png'}
              width={300}
            />
            <h3 className="font-semibold text-lg mb-1">Profile</h3>
            <p className="text-sm font-medium text-gray-400 text-left mb-4">
              Make your profile stand out with a striking avatar
            </p>
            {errors.coverImage && (
              <p className="text-red-400 text-xs mb-2">{errors.coverImage}</p>
            )}
            <button
              className="border cursor-pointer font-semibold border-white w-full rounded-md px-4 py-2 text-sm hover:bg-white hover:text-black transition"
              type="button"
              onClick={() => fileInputRef.current?.click()}
            >
              Change Avatar
            </button>
            <p className="text-[10px] text-gray-500 text-center mt-2">
              JPEG, PNG, WebP or GIF. Max {MAX_SIZE_MB}MB.
            </p>
            <input
              ref={fileInputRef}
              accept="image/jpeg,image/png,image/webp,image/gif"
              className="hidden"
              type="file"
              onChange={handleImageSelect}
            />
          </div>
        </div>
      )}

      <AvatarCrop
        imageSrc={rawImageSrc}
        open={cropOpen}
        onCropComplete={handleCropComplete}
        onOpenChange={setCropOpen}
      />
    </div>
  );
};

export default EditProfile;

