'use client';

import { useEffect, useRef, useState } from 'react';
import { useLoading } from '@/context/LoadingContext';
import { usePlayback } from '@/context/PlaybackContext';
import {
  ANNOUNCEMENT_EVENT,
  AnnouncementDetail,
  useAnnounce,
} from '@/hooks/useAnnounce';

type LiveMessage = {
  id: number;
  message: string;
};

export default function AccessibilityAnnouncer() {
  const { playlist, currentIndex, queue, trackError } = usePlayback();
  const { isAnyLoading } = useLoading();
  const announce = useAnnounce();
  const [politeMessage, setPoliteMessage] = useState<LiveMessage>({ id: 0, message: '' });
  const [assertiveMessage, setAssertiveMessage] = useState<LiveMessage>({
    id: 0,
    message: '',
  });
  const previousTrackId = useRef<string | null>(null);
  const previousQueueLength = useRef<number | null>(null);
  const previousLoading = useRef(false);

  useEffect(() => {
    const handleAnnouncement = (event: Event) => {
      const detail = (event as CustomEvent<AnnouncementDetail>).detail;
      if (!detail?.message) return;

      if (detail.priority === 'assertive') {
        setAssertiveMessage((previous) => ({ id: previous.id + 1, message: detail.message }));
      } else {
        setPoliteMessage((previous) => ({ id: previous.id + 1, message: detail.message }));
      }
    };

    window.addEventListener(ANNOUNCEMENT_EVENT, handleAnnouncement);
    return () => window.removeEventListener(ANNOUNCEMENT_EVENT, handleAnnouncement);
  }, []);

  useEffect(() => {
    const track = playlist[currentIndex];
    if (!track || previousTrackId.current === null) {
      previousTrackId.current = track?.id ?? null;
      return;
    }

    if (track.id !== previousTrackId.current) {
      announce(`Now playing ${track.title} by ${track.artist}`, 'polite');
      previousTrackId.current = track.id;
    }
  }, [announce, currentIndex, playlist]);

  useEffect(() => {
    if (previousQueueLength.current === null) {
      previousQueueLength.current = queue.length;
      return;
    }

    if (queue.length !== previousQueueLength.current) {
      const count = queue.length === 1 ? '1 track' : `${queue.length} tracks`;
      announce(`Queue updated. ${count} in queue.`, 'polite');
      previousQueueLength.current = queue.length;
    }
  }, [announce, queue.length]);

  useEffect(() => {
    if (trackError) announce(trackError, 'assertive');
  }, [announce, trackError]);

  useEffect(() => {
    const loading = isAnyLoading();
    if (previousLoading.current && !loading) announce('Loading complete', 'polite');
    previousLoading.current = loading;
  }, [announce, isAnyLoading, isAnyLoading()]);

  return (
    <>
      <div
        key={`polite-${politeMessage.id}`}
        aria-atomic="true"
        aria-live="polite"
        className="sr-only"
      >
        {politeMessage.message}
      </div>
      <div
        key={`assertive-${assertiveMessage.id}`}
        aria-atomic="true"
        aria-live="assertive"
        className="sr-only"
        role="alert"
      >
        {assertiveMessage.message}
      </div>
    </>
  );
}

'use client';

import { useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { parseEther } from 'viem';
import { useWriteContract, useWaitForTransactionReceipt } from 'wagmi';
import { contractAddress, abi } from '@/config/abi';

interface BuyButtonProps {
  tokenId: string;
  price: string;
  label: string;
}

const BuyButton = ({ tokenId, price, label }: BuyButtonProps) => {
  const { writeContract, data: hash, isPending } = useWriteContract();
  const queryClient = useQueryClient();

  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({
    hash,
  });

  // #142 — without this, a confirmed purchase never invalidates the NFT
  // collection reads (useNFTCollection's balanceOf/getArtistSongs/getSongById
  // calls), so the profile/collection pages keep showing stale ownership
  // data until a full page refresh. wagmi's contract-read hooks are backed
  // by the same TanStack Query cache these queryKey prefixes address, so
  // this invalidates them wherever they're mounted — including on a
  // completely different page than the one the purchase happened on.
  useEffect(() => {
    if (isSuccess) {
      toast.success('Purchase confirmed! Your collection has been updated.');
      queryClient.invalidateQueries({ queryKey: ['readContract'] });
      queryClient.invalidateQueries({ queryKey: ['readContracts'] });
    }
  }, [isSuccess, queryClient]);

  const handleBuy = async () => {
    try {
      // Extract numeric ID from 'music-1', 'event-1', etc.
      const numericId = parseInt(tokenId.split('-')[1]);

      writeContract({
        address: contractAddress,
        abi: abi,
        functionName: 'purchase', 
        args: [BigInt(numericId)], 
        value: parseEther(price.split(' ')[0]),
      });

    } catch (error: any) {
      toast.error(error?.message || 'Transaction failed');
    }
  };

  // Helper to parse ETH
  // function parseEther(value: string) {
  //   return BigInt(parseFloat(value) * 10 ** 18);
  // }

  const isProcessing = isPending || isConfirming;

  return (
    <button 
      className="border-gray-600 border text-white px-4 py-2 rounded-2xl transition-colors text-sm mb-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
      disabled={isProcessing}
      onClick={handleBuy}
    >
      {isProcessing ? (
        <>
          <Loader2 className="h-3 w-3 animate-spin" />
          {isConfirming ? 'Confirming...' : 'Pending...'}
        </>
      ) : (
        label
      )}
    </button>
  );
};

export default BuyButton;

'use client';

import { AlertTriangle, RefreshCw, WifiOff, SearchX, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';

type ErrorVariant = 'generic' | 'network' | 'not-found';

interface ErrorStateProps {
  title?: string;
  message?: string;
  illustration?: React.ReactNode;
  variant?: ErrorVariant;
  onRetry?: () => void;
  isRetrying?: boolean;
  className?: string;
}

const variantIllustrations: Record<ErrorVariant, React.ReactNode> = {
  generic: <AlertTriangle className="text-brand" size={48} />,
  network: <WifiOff className="text-brand" size={48} />,
  'not-found': <SearchX className="text-brand" size={48} />,
};

const variantTitles: Record<ErrorVariant, string> = {
  generic: 'Something went wrong',
  network: 'Network error',
  'not-found': 'Not found',
};

const variantMessages: Record<ErrorVariant, string> = {
  generic: 'An unexpected error occurred. Please try again.',
  network: 'Unable to connect. Check your internet connection and try again.',
  'not-found': 'The content you are looking for could not be found.',
};

export default function ErrorState({
  title,
  message,
  illustration,
  variant = 'generic',
  onRetry,
  isRetrying = false,
  className,
}: ErrorStateProps) {
  const displayTitle = title ?? variantTitles[variant];
  const displayMessage = message ?? variantMessages[variant];
  const displayIllustration = illustration ?? variantIllustrations[variant];

  return (
    <div
      aria-live="assertive"
      className="flex flex-col items-center justify-center gap-3 py-10 text-center"
      role="alert"
    >
      <AlertTriangle className="text-brand" size={32} />
      <p className="text-sm text-on-muted max-w-xs">{message}</p>
      {onRetry && (
        <button
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-brand hover:bg-brand-hover rounded-full transition-colors disabled:opacity-60 disabled:pointer-events-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand"
          disabled={isRetrying}
          onClick={onRetry}
        >
          {isRetrying ? <Loader2 className="animate-spin" size={14} /> : <RefreshCw size={14} />}
          {isRetrying ? 'Retrying...' : 'Retry'}
        </button>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback, useRef } from 'react';
import Image from 'next/image';
import { GripVertical, Trash2, X } from 'lucide-react';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { usePlayback } from '@/context/PlaybackContext';

interface QueueDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface DragItem {
  index: number;
}

export function QueueDrawer({ open, onOpenChange }: QueueDrawerProps) {
  const { queue, removeFromQueue, clearQueue, reorderQueue } = usePlayback();
  const [removeIndex, setRemoveIndex] = useState<number | null>(null);
  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const dragItem = useRef<DragItem | null>(null);
  const dragOverItem = useRef<DragItem | null>(null);

  const handleDragStart = useCallback((index: number) => {
    dragItem.current = { index };
  }, []);

  const handleDragEnter = useCallback((index: number) => {
    dragOverItem.current = { index };
  }, []);

  const handleDragEnd = useCallback(() => {
    if (
      dragItem.current &&
      dragOverItem.current &&
      dragItem.current.index !== dragOverItem.current.index
    ) {
      reorderQueue(dragItem.current.index, dragOverItem.current.index);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  }, [reorderQueue]);

  const handleRemove = useCallback((index: number) => {
    removeFromQueue(index);
    setRemoveIndex(null);
  }, [removeFromQueue]);

  const handleClear = useCallback(() => {
    clearQueue();
    setShowClearConfirm(false);
  }, [clearQueue]);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        aria-expanded={open}
        aria-label="Track queue"
        className="touch-pan-y bg-[#161616] text-white border-l-white/10 flex flex-col"
        role="dialog"
        side="right"
      >
        <SheetHeader>
          <SheetTitle className="text-white flex items-center justify-between">
            <span>Up next</span>
            <span className="text-sm font-normal text-gray-400">
              {queue.length} {queue.length === 1 ? 'track' : 'tracks'}
            </span>
          </SheetTitle>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-4 pb-4">
          {queue.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-gray-400">
              <p className="text-sm">Your queue is empty.</p>
              <p className="text-xs mt-1">Add tracks from the player or browse page.</p>
            </div>
          ) : (
            <ul className="space-y-1" role="list">
              {queue.map((track, index) => (
                <li
                  key={`${track.id}-${index}`}
                  draggable
                  className="flex items-center gap-2 rounded-md bg-white/5 px-2 py-2 hover:bg-white/10 transition cursor-default"
                  onDragEnd={handleDragEnd}
                  onDragEnter={() => handleDragEnter(index)}
                  onDragOver={(e) => e.preventDefault()}
                  onDragStart={() => handleDragStart(index)}
                >
                  <div
                    aria-label={`Drag to reorder ${track.title}`}
                    className="cursor-grab active:cursor-grabbing text-gray-500 hover:text-white shrink-0"
                    role="button"
                    tabIndex={0}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                      }
                    }}
                  >
                    <GripVertical size={16} />
                  </div>

                  <div className="relative w-10 h-10 rounded overflow-hidden shrink-0">
                    <Image
                      fill
                      alt={track.title}
                      className="object-cover"
                      src={track.cover || '/placeholder-cover.svg'}
                      onError={(e) => {
                        e.currentTarget.src = '/placeholder-cover.svg';
                      }}
                    />
                  </div>

                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium text-white">{track.title}</p>
                    <p className="truncate text-xs text-gray-400">{track.artist}</p>
                  </div>

                  {removeIndex === index ? (
                    <div className="flex items-center gap-1.5 shrink-0">
                      <button
                        className="text-xs text-red-400 hover:text-red-300 underline"
                        onClick={() => handleRemove(index)}
                      >
                        Remove
                      </button>
                      <button
                        aria-label="Cancel remove"
                        className="text-gray-400 hover:text-white"
                        onClick={() => setRemoveIndex(null)}
                      >
                        <X size={14} />
                      </button>
                    </div>
                  ) : (
                    <button
                      aria-label={`Remove ${track.title} from queue`}
                      className="shrink-0 text-gray-400 hover:text-white opacity-0 group-hover:opacity-100 transition"
                      onClick={() => setRemoveIndex(index)}
                    >
                      <Trash2 size={14} />
                    </button>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>

        {queue.length > 0 && (
          <div className="px-4 pb-4 border-t border-white/10 pt-3">
            {showClearConfirm ? (
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-400">Clear all tracks?</span>
                <div className="flex items-center gap-2">
                  <button
                    className="text-xs text-red-400 hover:text-red-300 underline"
                    onClick={handleClear}
                  >
                    Yes
                  </button>
                  <button
                    className="text-xs text-gray-400 hover:text-white"
                    onClick={() => setShowClearConfirm(false)}
                  >
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <button
                className="text-xs text-gray-400 underline hover:text-white"
                onClick={() => setShowClearConfirm(true)}
              >
                Clear queue
              </button>
            )}
          </div>
        )}
      </SheetContent>
    </Sheet>
  );
}

"use client"

import { useState, useEffect, useRef } from "react"

interface Card {
  id: number
  title: string
  subtitle: string
  color: string
  gradient: string
}

interface AutoStackedCardsProps {
  cards?: Card[]
  interval?: number
  pauseOnHover?: boolean
  showProgress?: boolean
}

const defaultCards: Card[] = [
  {
    id: 1,
    title: "Mountain Adventure",
    subtitle: "Explore breathtaking peaks",
    color: "bg-blue-500",
    gradient: "from-blue-400 to-blue-600",
  },
  {
    id: 2,
    title: "Ocean Depths",
    subtitle: "Dive into crystal waters",
    color: "bg-teal-500",
    gradient: "from-teal-400 to-teal-600",
  },
  {
    id: 3,
    title: "Forest Trails",
    subtitle: "Walk through ancient woods",
    color: "bg-green-500",
    gradient: "from-green-400 to-green-600",
  },
  {
    id: 4,
    title: "Desert Sunset",
    subtitle: "Watch the golden horizon",
    color: "bg-orange-500",
    gradient: "from-orange-400 to-orange-600",
  },
  {
    id: 5,
    title: "City Lights",
    subtitle: "Experience urban energy",
    color: "bg-purple-500",
    gradient: "from-purple-400 to-purple-600",
  },
]

export default function AutoStackedCards({
  cards = defaultCards,
  interval = 4000,
  pauseOnHover = true,
  showProgress = true,
}: AutoStackedCardsProps) {
  const [currentIndex, setCurrentIndex] = useState(0)
  const [isHovered, setIsHovered] = useState(false)
  const [progress, setProgress] = useState(0)
  const intervalRef = useRef<NodeJS.Timeout | null>(null)
  const progressRef = useRef<NodeJS.Timeout | null>(null)

  // Auto-advance cards
  useEffect(() => {
    if (isHovered && pauseOnHover) return

    intervalRef.current = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % cards.length)
      setProgress(0) // Reset progress when card changes
    }, interval)

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current)
    }
  }, [cards.length, interval, isHovered, pauseOnHover])

  // Progress bar animation
  useEffect(() => {
    if (isHovered && pauseOnHover) return

    setProgress(0)
    const startTime = Date.now()

    const updateProgress = () => {
      const elapsed = Date.now() - startTime
      const newProgress = Math.min((elapsed / interval) * 100, 100)
      setProgress(newProgress)

      if (newProgress < 100) {
        progressRef.current = setTimeout(updateProgress, 16) // ~60fps
      }
    }

    updateProgress()

    return () => {
      if (progressRef.current) clearTimeout(progressRef.current)
    }
  }, [currentIndex, interval, isHovered, pauseOnHover])

  const handleMouseEnter = () => {
    if (pauseOnHover) {
      setIsHovered(true)
      if (intervalRef.current) clearInterval(intervalRef.current)
      if (progressRef.current) clearTimeout(progressRef.current)
    }
  }

  const handleMouseLeave = () => {
    if (pauseOnHover) {
      setIsHovered(false)
    }
  }

  const handleCardClick = (index: number) => {
    if (index !== currentIndex) {
      setCurrentIndex(index)
      setProgress(0)
    }
  }

  return (
    <div className="flex flex-col items-center space-y-6">
      {/* Main Card Stack */}
      <div
        className="relative w-80 h-96 cursor-pointer"
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        {cards.map((card, index) => {
          const position = (index - currentIndex + cards.length) % cards.length
          const isActive = position === 0
          const isNext = position === 1
          const isPrev = position === cards.length - 1
          const isSecondNext = position === 2
          const isSecondPrev = position === cards.length - 2

          // Calculate transform values for smooth stacking
          let translateX = 0
          let translateY = 0
          let scale = 1
          let opacity = 1
          let zIndex = 0
          let rotateZ = 0
          let blur = 0

          if (isActive) {
            zIndex = 50
            scale = 1
            opacity = 1
          } else if (isNext) {
            translateX = 12
            translateY = 8
            scale = 0.96
            opacity = 0.85
            zIndex = 40
            rotateZ = 2
          } else if (isPrev) {
            translateX = -12
            translateY = 8
            scale = 0.96
            opacity = 0.85
            zIndex = 40
            rotateZ = -2
          } else if (isSecondNext) {
            translateX = 24
            translateY = 16
            scale = 0.92
            opacity = 0.7
            zIndex = 30
            rotateZ = 4
            blur = 1
          } else if (isSecondPrev) {
            translateX = -24
            translateY = 16
            scale = 0.92
            opacity = 0.7
            zIndex = 30
            rotateZ = -4
            blur = 1
          } else {
            translateX = 0
            translateY = 24
            scale = 0.88
            opacity = 0.5
            zIndex = 20
            blur = 2
          }

          return (
            <div
              key={card.id}
              className={`absolute inset-0 transition-all duration-700 ease-out cursor-pointer`}
              style={{
                transform: `
                  translateX(${translateX}px) 
                  translateY(${translateY}px) 
                  scale(${scale}) 
                  rotateZ(${rotateZ}deg)
                `,
                opacity,
                zIndex,
                filter: blur > 0 ? `blur(${blur}px)` : "none",
                transitionTimingFunction: "cubic-bezier(0.4, 0, 0.2, 1)",
              }}
              onClick={() => handleCardClick(index)}
            >
              <div
                className={`w-full h-full bg-gradient-to-br ${card.gradient} rounded-2xl shadow-2xl overflow-hidden relative group`}
                style={{
                  boxShadow: isActive
                    ? "0 25px 50px -12px rgba(0, 0, 0, 0.25), 0 0 0 1px rgba(255, 255, 255, 0.1)"
                    : "0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 0 0 1px rgba(255, 255, 255, 0.05)",
                }}
              >
                {/* Card Content */}
                <div className="absolute inset-0 p-8 flex flex-col justify-between text-white">
                  {/* Top Section */}
                  <div className="space-y-2">
                    <div className="w-12 h-12 bg-white/20 rounded-xl backdrop-blur-sm flex items-center justify-center">
                      <div className="w-6 h-6 bg-white/40 rounded-lg" />
                    </div>
                  </div>

                  {/* Bottom Section */}
                  <div className="space-y-3">
                    <h3 className="text-2xl font-bold leading-tight">{card.title}</h3>
                    <p className="text-white/80 text-sm leading-relaxed">{card.subtitle}</p>

                    {/* Card number indicator */}
                    <div className="flex items-center space-x-2 pt-2">
                      <div className="w-8 h-1 bg-white/30 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-white transition-all duration-300"
                          style={{
                            width: isActive ? `${progress}%` : "0%",
                          }}
                        />
                      </div>
                      <span className="text-xs text-white/60 font-medium">{String(index + 1).padStart(2, "0")}</span>
                    </div>
                  </div>
                </div>

                {/* Hover overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />

                {/* Subtle pattern overlay */}
                <div
                  className="absolute inset-0 opacity-10"
                  style={{
                    backgroundImage: `radial-gradient(circle at 20% 80%, rgba(255,255,255,0.2) 0%, transparent 50%), 
                                     radial-gradient(circle at 80% 20%, rgba(255,255,255,0.1) 0%, transparent 50%)`,
                  }}
                />
              </div>
            </div>
          )
        })}
      </div>

      {/* Progress Indicators */}
      {showProgress && (
        <div className="flex space-x-3">
          {cards.map((_, index) => (
            <button
              key={index}
              className={`relative w-12 h-2 rounded-full overflow-hidden transition-all duration-300 ${
                index === currentIndex ? "bg-gray-300" : "bg-gray-200 hover:bg-gray-250"
              }`}
              onClick={() => handleCardClick(index)}
            >
              {index === currentIndex && (
                <div
                  className="absolute left-0 top-0 h-full bg-gradient-to-r from-blue-500 to-purple-500 transition-all duration-75 ease-linear"
                  style={{ width: `${progress}%` }}
                />
              )}
            </button>
          ))}
        </div>
      )}

      {/* Card Counter */}
      <div className="text-center space-y-1">
        <div className="text-2xl font-bold text-gray-800">
          {String(currentIndex + 1).padStart(2, "0")} / {String(cards.length).padStart(2, "0")}
        </div>
        <div className="text-sm text-gray-500">{isHovered && pauseOnHover ? "Paused" : "Auto-playing"}</div>
      </div>
    </div>
  )
}

