import { usePlayback, type Track } from '@/context/PlaybackContext';
import { Auth } from '@/hooks/useAuth';
import FullScreenLoader from './FullScreenLoader';

type SpotlightItem = Track & {
  eyebrow: string;
  description: string;
  accent: string;
};

const spotlightItems: SpotlightItem[] = [
  {
    id: 'music-1',
    title: 'Bigger',
    artist: 'Wiffi Drips',
    cover: '/wif.jpg',
    eyebrow: 'Trending track',
    description: 'Turn up the energy with one of this week’s most collected sounds.',
    accent: '#D2045B',
  },
  {
    id: 'music-2',
    title: 'ASILW',
    artist: 'Mchivir',
    cover: '/chilli.jpg',
    eyebrow: 'Spotlight album',
    description: 'A fresh release from an independent voice making waves right now.',
    accent: '#885FA8',
  },
  {
    id: 'music-3',
    title: 'Bad Guy',
    artist: 'Soldier Cat',
    cover: '/cat.png',
    eyebrow: 'Fan favourite',
    description: 'Discover a standout record from the AudioBlocks community.',
    accent: '#B6195B',
  },
];

const PREVIEW_DURATION = 30;
const ROTATION_INTERVAL = 6000;

const HeroCarousel = () => {
  const { setShowAuthFlow } = useDynamicContext();
  const router = useRouter();
  const { isConnected } = useAccount();
  const { setShouldTriggerSignature, loading } = Auth();
  const { playTrack } = usePlayback();
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isPreviewing, setIsPreviewing] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const touchStartX = useRef<number | null>(null);

  const activeItem = spotlightItems[activeIndex];

  const stopPreview = useCallback(() => {
    const audio = audioRef.current;
    if (audio) {
      audio.pause();
      audio.currentTime = 0;
    }
    setIsPreviewing(false);
  }, []);

  const selectSlide = useCallback(
    (index: number) => {
      stopPreview();
      setActiveIndex((index + spotlightItems.length) % spotlightItems.length);
    },
    [stopPreview],
  );

  const nextSlide = useCallback(() => {
    selectSlide(activeIndex + 1);
  }, [activeIndex, selectSlide]);

  const previousSlide = useCallback(() => {
    selectSlide(activeIndex - 1);
  }, [activeIndex, selectSlide]);

  const togglePreview = useCallback(() => {
    const audio = audioRef.current;
    if (!audio) return;

    if (isPreviewing) {
      stopPreview();
      return;
    }

    audio.currentTime = 0;
    audio.volume = 0.8;
    const playPromise = audio.play();
    if (playPromise) {
      playPromise
        .then(() => setIsPreviewing(true))
        .catch(() => setIsPreviewing(false));
    }
  }, [isPreviewing, stopPreview]);

  const handleStream = () => {
    const token = Cookies.get('audioblocks_jwt');
    if (!isConnected) {
      setShowAuthFlow(true);
      setShouldTriggerSignature(true);
    } else if (!token) {
      setShouldTriggerSignature(true);
    } else {
      router.push('/dashboard/profile/edit');
    }
  };

  useEffect(() => {
    if (isPaused) return;
    const timer = window.setInterval(nextSlide, ROTATION_INTERVAL);
    return () => window.clearInterval(timer);
  }, [isPaused, nextSlide]);

  useEffect(() => {
    stopPreview();
  }, [activeIndex, stopPreview]);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const stopAtThirtySeconds = () => {
      if (audio.currentTime >= PREVIEW_DURATION) stopPreview();
    };
    audio.addEventListener('timeupdate', stopAtThirtySeconds);
    audio.addEventListener('ended', stopPreview);
    return () => {
      audio.removeEventListener('timeupdate', stopAtThirtySeconds);
      audio.removeEventListener('ended', stopPreview);
    };
  }, [stopPreview]);

  useEffect(() => () => stopPreview(), [stopPreview]);

  const handlePointerDown = (event: React.PointerEvent<HTMLElement>) => {
    touchStartX.current = event.clientX;
  };

  const handlePointerUp = (event: React.PointerEvent<HTMLElement>) => {
    if (touchStartX.current === null) return;
    const distance = event.clientX - touchStartX.current;
    touchStartX.current = null;
    if (Math.abs(distance) < 40) return;
    if (distance > 0) previousSlide();
    else nextSlide();
  };

  const handleMobilePreview = () => {
    if (window.matchMedia('(max-width: 767px)').matches) togglePreview();
  };

  return (
    <section
      aria-label="Trending music spotlight"
      className="relative mx-auto h-[280px] w-full overflow-hidden text-white md:h-[400px]"
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node)) setIsPaused(false);
      }}
      onFocus={() => setIsPaused(true)}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
    >
      <div aria-hidden="true" className="absolute inset-0 bg-[#100b10]" />
      <div
        aria-hidden="true"
        className="absolute -right-20 -top-32 h-96 w-96 rounded-full blur-[110px] transition-colors duration-700"
        style={{ backgroundColor: `${activeItem.accent}80` }}
      />

      <div className="relative mx-auto flex h-full w-11/12 max-w-7xl items-center justify-between gap-6 md:w-4/5">
        <div className="z-10 max-w-xl">
          <p className="mb-2 text-xs font-semibold uppercase tracking-[0.2em] text-[#F2AFC9] md:text-sm">
            {activeItem.eyebrow}
          </p>
          <h1 className="mb-1 text-2xl font-extrabold leading-tight md:text-5xl">
            {activeItem.title}
          </h1>
          <p className="mb-2 text-sm font-medium text-[#DACFD3] md:text-lg">{activeItem.artist}</p>
          <p className="mb-4 hidden max-w-md text-sm leading-relaxed text-[#DACFD3] md:block">
            {activeItem.description}
          </p>
          <div className="flex items-center gap-3">
            <button
              className="flex items-center gap-2 rounded-full bg-[#D2045B] px-4 py-2 text-sm font-medium transition hover:bg-[#B8043F] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#F2AFC9] md:px-6"
              onClick={handleStream}
            >
              Stream Now
              <ArrowRight aria-hidden="true" size={16} />
            </button>
            <button
              className="flex items-center gap-2 rounded-full border border-[#F2AFC9] px-4 py-2 text-sm font-medium transition hover:bg-[#885FA8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#F2AFC9]"
              onClick={() => {
                playTrack(activeItem);
                stopPreview();
              }}
            >
              <Play aria-hidden="true" fill="currentColor" size={14} />
              Play track
            </button>
          </div>
        </div>

        <button
          aria-label={isPreviewing ? `Pause preview of ${activeItem.title}` : `Preview ${activeItem.title}`}
          className="group relative h-40 w-40 shrink-0 overflow-hidden rounded-2xl border border-white/30 shadow-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#F2AFC9] md:h-64 md:w-64"
          type="button"
          onClick={handleMobilePreview}
          onMouseEnter={togglePreview}
          onMouseLeave={stopPreview}
        >
          <Image
            fill
            priority
            alt={`${activeItem.title} by ${activeItem.artist}`}
            className="object-cover transition duration-500 group-hover:scale-105"
            sizes="(max-width: 767px) 160px, 256px"
            src={activeItem.cover}
          />
          <span className="absolute inset-0 flex items-center justify-center bg-black/30">
            {isPreviewing ? <Pause fill="white" size={28} /> : <Play fill="white" size={28} />}
          </span>
          <span className="absolute bottom-2 left-2 rounded-full bg-black/60 px-2 py-1 text-[10px] uppercase tracking-wider">
            30 sec preview
          </span>
        </button>
      </div>

      <button
        aria-label="Previous spotlight"
        className="absolute left-2 top-1/2 z-20 -translate-y-1/2 rounded-full bg-black/40 p-2 transition hover:bg-[#D2045B] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white md:left-6"
        type="button"
        onClick={previousSlide}
      >
        <ArrowLeft size={18} />
      </button>
      <button
        aria-label="Next spotlight"
        className="absolute right-2 top-1/2 z-20 -translate-y-1/2 rounded-full bg-black/40 p-2 transition hover:bg-[#D2045B] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white md:right-6"
        type="button"
        onClick={nextSlide}
      >
        <ArrowRight size={18} />
      </button>

      <div aria-label="Spotlight slides" className="absolute bottom-4 left-1/2 z-20 flex -translate-x-1/2 gap-2" role="tablist">
        {spotlightItems.map((item, index) => (
          <button
            key={item.id}
            aria-label={`Show ${item.title}`}
            aria-selected={index === activeIndex}
            className={`h-2 rounded-full transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white ${index === activeIndex ? 'w-7 bg-[#D2045B]' : 'w-2 bg-white/60'}`}
            role="tab"
            type="button"
            onClick={() => selectSlide(index)}
          />
        ))}
      </div>

      <audio
        ref={audioRef}
        aria-hidden="true"
        preload="none"
        src={`${process.env.NEXT_PUBLIC_API_URL || ''}/stream/${activeItem.id}`}
      />
      {loading && <FullScreenLoader />}
    </section>
  );
};

export default HeroCarousel;

"use client"

import { useState, useEffect, useRef, useCallback } from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { Button } from "@/components/ui/button"

interface SlideItem {
  id: number
  title: string
  subtitle: string
  color: string
  gradient: string
  textColor?: string
}

interface LayeredDepthSliderProps {
  slides?: SlideItem[]
  interval?: number
  pauseOnHover?: boolean
  showControls?: boolean
  showProgress?: boolean
  size?: "sm" | "md" | "lg"
}

const defaultSlides: SlideItem[] = [
  {
    id: 1,
    title: "Mountain Peak",
    subtitle: "Breathtaking alpine adventures await",
    color: "bg-blue-600",
    gradient: "from-blue-500 via-blue-600 to-indigo-700",
    textColor: "text-white",
  },
  {
    id: 2,
    title: "Ocean Waves",
    subtitle: "Dive into crystal clear waters",
    color: "bg-teal-600",
    gradient: "from-teal-400 via-teal-600 to-cyan-700",
    textColor: "text-white",
  },
  {
    id: 3,
    title: "Forest Trail",
    subtitle: "Walk through ancient woodlands",
    color: "bg-green-600",
    gradient: "from-green-500 via-green-600 to-emerald-700",
    textColor: "text-white",
  },
  {
    id: 4,
    title: "Desert Sunset",
    subtitle: "Golden horizons stretch endlessly",
    color: "bg-orange-600",
    gradient: "from-orange-400 via-orange-600 to-red-700",
    textColor: "text-white",
  },
  {
    id: 5,
    title: "City Lights",
    subtitle: "Urban energy pulses through the night",
    color: "bg-purple-600",
    gradient: "from-purple-500 via-purple-600 to-pink-700",
    textColor: "text-white",
  },
  {
    id: 6,
    title: "Arctic Ice",
    subtitle: "Pristine wilderness in frozen beauty",
    color: "bg-cyan-600",
    gradient: "from-cyan-400 via-cyan-600 to-blue-700",
    textColor: "text-white",
  },
]

export default function LayeredDepthSlider({
  slides = defaultSlides,
  interval = 4000,
  pauseOnHover = true,
  showControls = true,
  showProgress = true,
  size = "md",
}: LayeredDepthSliderProps) {
  const [currentIndex, setCurrentIndex] = useState(0)
  const [isAnimating, setIsAnimating] = useState(false)
  const [isHovered, setIsHovered] = useState(false)
  const [progress, setProgress] = useState(0)
  const intervalRef = useRef<NodeJS.Timeout | null>(null)
  const progressRef = useRef<NodeJS.Timeout | null>(null)

  // Size configurations
  const sizeConfig = {
    sm: { width: "w-80", height: "h-48", text: "text-lg" },
    md: { width: "w-96", height: "h-64", text: "text-xl" },
    lg: { width: "w-[28rem]", height: "h-80", text: "text-2xl" },
  }

  const config = sizeConfig[size]

  // Auto-advance slides
  useEffect(() => {
    if (isHovered && pauseOnHover) return

    intervalRef.current = setInterval(() => {
      slideNext()
    }, interval)

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current)
    }
  }, [currentIndex, interval, isHovered, pauseOnHover, slideNext])

  // Progress animation
  useEffect(() => {
    if (isHovered && pauseOnHover) return

    setProgress(0)
    const startTime = Date.now()

    const updateProgress = () => {
      const elapsed = Date.now() - startTime
      const newProgress = Math.min((elapsed / interval) * 100, 100)
      setProgress(newProgress)

      if (newProgress < 100) {
        progressRef.current = setTimeout(updateProgress, 16) // ~60fps
      }
    }

    updateProgress()

    return () => {
      if (progressRef.current) clearTimeout(progressRef.current)
    }
  }, [currentIndex, interval, isHovered, pauseOnHover])

  const slideNext = useCallback(() => {
    if (isAnimating) return
    setIsAnimating(true)
    setCurrentIndex((prev) => (prev + 1) % slides.length)
    setProgress(0)
    setTimeout(() => setIsAnimating(false), 800)
  }, [isAnimating, slides.length])

  const slidePrev = () => {
    if (isAnimating) return
    setIsAnimating(true)
    setCurrentIndex((prev) => (prev - 1 + slides.length) % slides.length)
    setProgress(0)
    setTimeout(() => setIsAnimating(false), 800)
  }

  const goToSlide = (index: number) => {
    if (index !== currentIndex && !isAnimating) {
      setIsAnimating(true)
      setCurrentIndex(index)
      setProgress(0)
      setTimeout(() => setIsAnimating(false), 800)
    }
  }

  const handleMouseEnter = () => {
    if (pauseOnHover) {
      setIsHovered(true)
      if (intervalRef.current) clearInterval(intervalRef.current)
      if (progressRef.current) clearTimeout(progressRef.current)
    }
  }

  const handleMouseLeave = () => {
    if (pauseOnHover) {
      setIsHovered(false)
    }
  }

  return (
    <div className="flex flex-col items-center space-y-6">
      {/* Main Slider Container */}
      <div
        className={`relative ${config.width} ${config.height} perspective-1000`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="relative w-full h-full preserve-3d">
          {slides.map((slide, index) => {
            const offset = (index - currentIndex + slides.length) % slides.length

            // Calculate transform values for layered depth effect
            let translateX = 0
            let translateY = 0
            let translateZ = 0
            let scale = 1
            let opacity = 1
            let zIndex = 0
            let rotateY = 0
            let blur = 0

            if (offset === 0) {
              // Active slide - front and center
              zIndex = 50
              scale = 1
              opacity = 1
            } else if (offset === 1) {
              // Next slide - right side, slightly behind
              translateX = 40
              translateY = 10
              translateZ = -30
              scale = 0.92
              opacity = 0.85
              zIndex = 40
              rotateY = -8
            } else if (offset === slides.length - 1) {
              // Previous slide - left side, slightly behind
              translateX = -40
              translateY = 10
              translateZ = -30
              scale = 0.92
              opacity = 0.85
              zIndex = 40
              rotateY = 8
            } else if (offset === 2) {
              // Second next - further right and back
              translateX = 70
              translateY = 20
              translateZ = -60
              scale = 0.84
              opacity = 0.7
              zIndex = 30
              rotateY = -15
              blur = 1
            } else if (offset === slides.length - 2) {
              // Second previous - further left and back
              translateX = -70
              translateY = 20
              translateZ = -60
              scale = 0.84
              opacity = 0.7
              zIndex = 30
              rotateY = 15
              blur = 1
            } else {
              // Far background slides
              translateX = 0
              translateY = 30
              translateZ = -100
              scale = 0.76
              opacity = 0.5
              zIndex = 20
              blur = 2
            }

            return (
              <div
                key={slide.id}
                className={`absolute inset-0 transition-all duration-800 ease-out cursor-pointer`}
                style={{
                  transform: `
                    translateX(${translateX}px) 
                    translateY(${translateY}px) 
                    translateZ(${translateZ}px) 
                    scale(${scale}) 
                    rotateY(${rotateY}deg)
                  `,
                  opacity,
                  zIndex,
                  filter: blur > 0 ? `blur(${blur}px)` : "none",
                  transitionTimingFunction: "cubic-bezier(0.25, 0.46, 0.45, 0.94)",
                }}
                onClick={() => goToSlide(index)}
              >
                <div
                  className={`w-full h-full bg-gradient-to-br ${slide.gradient} rounded-2xl shadow-2xl overflow-hidden relative group`}
                  style={{
                    boxShadow:
                      offset === 0
                        ? "0 25px 50px -12px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.1)"
                        : "0 10px 25px -5px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(255, 255, 255, 0.05)",
                  }}
                >
                  {/* Background Pattern */}
                  <div
                    className="absolute inset-0 opacity-20"
                    style={{
                      backgroundImage: `
                        radial-gradient(circle at 25% 25%, rgba(255,255,255,0.3) 0%, transparent 50%),
                        radial-gradient(circle at 75% 75%, rgba(255,255,255,0.2) 0%, transparent 50%)
                      `,
                    }}
                  />

                  {/* Content */}
                  <div
                    className={`absolute inset-0 p-6 flex flex-col justify-between ${slide.textColor || "text-white"}`}
                  >
                    {/* Top Section - Icon/Logo Area */}
                    <div className="space-y-2">
                      <div className="w-12 h-12 bg-white/20 rounded-xl backdrop-blur-sm flex items-center justify-center">
                        <div className="w-6 h-6 bg-white/40 rounded-lg" />
                      </div>
                    </div>

                    {/* Bottom Section - Text Content */}
                    <div className="space-y-3">
                      <h3 className={`${config.text} font-bold leading-tight`}>{slide.title}</h3>
                      <p className="text-white/90 text-sm leading-relaxed">{slide.subtitle}</p>

                      {/* Progress bar for active slide */}
                      {offset === 0 && showProgress && (
                        <div className="flex items-center space-x-3 pt-2">
                          <div className="flex-1 h-1 bg-white/20 rounded-full overflow-hidden">
                            <div
                              className="h-full bg-white transition-all duration-100 ease-linear"
                              style={{ width: `${progress}%` }}
                            />
                          </div>
                          <span className="text-xs text-white/70 font-medium min-w-[2rem]">
                            {String(index + 1).padStart(2, "0")}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Hover Overlay */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                </div>
              </div>
            )
          })}
        </div>

        {/* Navigation Controls */}
        {showControls && (
          <>
            <Button
              className="absolute left-4 top-1/2 transform -translate-y-1/2 z-60 bg-white/10 hover:bg-white/20 text-white border-white/20 backdrop-blur-sm"
              disabled={isAnimating}
              size="icon"
              variant="outline"
              onClick={slidePrev}
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>

            <Button
              className="absolute right-4 top-1/2 transform -translate-y-1/2 z-60 bg-white/10 hover:bg-white/20 text-white border-white/20 backdrop-blur-sm"
              disabled={isAnimating}
              size="icon"
              variant="outline"
              onClick={slideNext}
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </>
        )}
      </div>

      {/* Slide Indicators */}
      <div className="flex space-x-2">
        {slides.map((_, index) => (
          <button
            key={index}
            className={`w-3 h-3 rounded-full transition-all duration-300 ${
              index === currentIndex ? "bg-blue-500 scale-110" : "bg-gray-300 hover:bg-gray-400"
            }`}
            onClick={() => goToSlide(index)}
          />
        ))}
      </div>

      {/* Status Display */}
      <div className="text-center space-y-1">
        <div className="text-lg font-semibold text-gray-800">
          {String(currentIndex + 1).padStart(2, "0")} / {String(slides.length).padStart(2, "0")}
        </div>
        <div className="text-sm text-gray-500">{isHovered && pauseOnHover ? "Paused" : "Auto-playing"}</div>
      </div>
    </div>
  )
}

