import { useMemo, useState } from 'react';
import Link from 'next/link';
import { CheckCircle2, Circle, X } from 'lucide-react';
import { useLocalStorage } from '@/hooks/useLocalStorage';
import { useNFTCollection } from '@/hooks/useNFTCollection';
import { useGetProfile } from '@/hooks/useProfile';

const DISMISS_KEY = 'audioblocks_profile_completion_dismissed';

interface ChecklistItem {
  label: string;
  done: boolean;
  href: string;
}

export function ProfileCompletion() {
  const { data: profile, isLoading } = useGetProfile();
  const { nftBalance, isLoading: nftLoading } = useNFTCollection();
  const [dismissed, setDismissed] = useLocalStorage(DISMISS_KEY, false);

  const items = useMemo<ChecklistItem[]>(() => [
    {
      label: 'Upload an avatar',
      done: !!profile?.profileImage,
      href: '/dashboard/profile/edit',
    },
    {
      label: 'Add a bio',
      done: !!profile?.bio,
      href: '/dashboard/profile/edit',
    },
    {
      label: 'Connect at least 1 social link',
      done: !!profile?.twitter,
      href: '/dashboard/profile/edit',
    },
    {
      label: 'Create your first collection',
      done: Number(nftBalance) > 0,
      href: '/dashboard/collection',
    },
  ], [profile, nftBalance]);

  const completedCount = items.filter((i) => i.done).length;
  const totalCount = items.length;
  const percentage = Math.round((completedCount / totalCount) * 100);
  const isComplete = completedCount === totalCount;

  if (isLoading || nftLoading || dismissed || isComplete) return null;

  return (
    <div className="relative mb-6 rounded-lg border border-border-dark bg-surface-elevated p-4">
      <button
        aria-label="Dismiss profile completion checklist"
        className="absolute top-3 right-3 text-gray-400 hover:text-white transition"
        onClick={() => setDismissed(true)}
      >
        <X size={16} />
      </button>

      <div className="flex items-center gap-4 mb-3">
        <div className="relative w-12 h-12">
          <svg className="w-12 h-12 -rotate-90" viewBox="0 0 36 36">
            <circle
              className="text-white/10" cx="18" cy="18"
              fill="none"
              r="15.5"
              stroke="currentColor"
              strokeWidth="3"
            />
            <circle
              className="text-brand" cx="18" cy="18"
              fill="none"
              r="15.5"
              stroke="currentColor"
              strokeDasharray={`${percentage * 0.97} 97`}
              strokeLinecap="round"
              strokeWidth="3"
            />
          </svg>
          <span className="absolute inset-0 flex items-center justify-center text-xs font-semibold text-white">
            {percentage}%
          </span>
        </div>
        <div>
          <h3 className="text-sm font-semibold text-white">Complete your profile</h3>
          <p className="text-xs text-gray-400">
            {completedCount} of {totalCount} tasks done
          </p>
        </div>
      </div>

      <ul className="space-y-2">
        {items.map((item) => (
          <li key={item.label}>
            <Link
              className="flex items-center gap-2 text-sm text-gray-300 hover:text-white transition"
              href={item.href}
            >
              {item.done ? (
                <CheckCircle2 className="text-green-500 shrink-0" size={16} />
              ) : (
                <Circle className="text-gray-500 shrink-0" size={16} />
              )}
              <span className={item.done ? 'line-through text-gray-500' : ''}>
                {item.label}
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

'use client';

import { memo, type KeyboardEvent, type ReactNode } from 'react';
import { Heart, Play } from 'lucide-react';
import { ArtworkImage } from '@/components/ui/ArtworkImage';

export type AudioCardVariant = 'compact' | 'standard' | 'wide';

export interface AudioCardActions {
  play?: ReactNode;
  save?: ReactNode;
}

export interface AudioCardProps {
  artworkUrl?: string | null;
  /** Backwards-compatible alias for artworkUrl. */
  imageUrl?: string | null;
  title: string;
  artist: string;
  duration?: string;
  variant?: AudioCardVariant;
  /** Legacy size aliases are supported for existing consumers. */
  size?: AudioCardVariant | 'sm' | 'md' | 'lg';
  isLoading?: boolean;
  altText?: string;
  onClick?: () => void;
  onPlay?: () => void;
  onSave?: () => void;
  actionButtons?: ReactNode;
  actions?: AudioCardActions;
  className?: string;
}

const variantClasses: Record<AudioCardVariant, string> = {
  compact: 'flex items-center gap-3 rounded-lg p-2',
  standard: 'flex flex-col gap-3 rounded-xl p-3',
  wide: 'flex items-center gap-5 rounded-2xl p-4 sm:p-5',
};

const artworkClasses: Record<AudioCardVariant, string> = {
  compact: 'h-12 w-12 shrink-0 rounded-md',
  standard: 'aspect-square w-full rounded-lg',
  wide: 'h-24 w-24 shrink-0 rounded-xl sm:h-32 sm:w-32',
};

const skeletonClasses: Record<AudioCardVariant, string> = {
  compact: 'h-16 w-full rounded-lg',
  standard: 'h-64 w-full rounded-xl',
  wide: 'h-40 w-full rounded-2xl',
};

function normalizeVariant(
  variant: AudioCardVariant | undefined,
  size: AudioCardProps['size'],
): AudioCardVariant {
  if (variant) return variant;
  if (size === 'sm') return 'compact';
  if (size === 'lg') return 'wide';
  if (size === 'md') return 'standard';
  return size ?? 'standard';
}

const AudioCard = memo(function AudioCard({
  artworkUrl,
  imageUrl,
  title,
  artist,
  duration,
  variant,
  size,
  isLoading = false,
  altText,
  onClick,
  onPlay,
  onSave,
  actionButtons,
  actions,
  className = '',
}: AudioCardProps) {
  const resolvedVariant = normalizeVariant(variant, size);
  const artwork = artworkUrl ?? imageUrl;
  const hasActions = Boolean(onPlay || onSave || actionButtons || actions?.play || actions?.save);

  if (isLoading) {
    return (
      <div
        aria-busy="true"
        className={`animate-pulse bg-surface-hover ${skeletonClasses[resolvedVariant]} ${className}`}
        data-testid="audio-card-skeleton"
      />
    );
  }

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!onClick || (event.key !== 'Enter' && event.key !== ' ')) return;
    event.preventDefault();
    onClick();
  };

  return (
    <div
      className={`group border border-transparent bg-transparent text-white transition-colors hover:border-border-dark hover:bg-surface-hover focus-visible:border-brand focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand focus-visible:ring-offset-2 focus-visible:ring-offset-black ${variantClasses[resolvedVariant]} ${onClick ? 'cursor-pointer' : ''} ${className}`}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      onClick={onClick}
      onKeyDown={handleKeyDown}
    >
      <div className={`relative overflow-hidden ${artworkClasses[resolvedVariant]}`}>
        <ArtworkImage
          alt={altText || `${title} by ${artist}`}
          className="h-full w-full object-cover"
          height={320}
          src={artwork}
          title={title}
          width={320}
        />
        {onPlay && (
          <button
            aria-label={`Play ${title}`}
            className="absolute inset-0 m-auto flex h-10 w-10 items-center justify-center rounded-full bg-brand text-white opacity-0 transition-opacity group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
            type="button"
            onClick={(event) => {
              event.stopPropagation();
              onPlay();
            }}
          >
            <Play aria-hidden="true" fill="currentColor" size={17} />
          </button>
        )}
      </div>

      <div className={`min-w-0 ${resolvedVariant === 'standard' ? 'flex-1' : ''}`}>
        <h3 className="truncate text-sm font-semibold text-white">{title}</h3>
        <p className="truncate text-xs text-on-muted">{artist}</p>
        {duration && <p className="mt-1 text-xs text-on-muted">{duration}</p>}
      </div>

      {hasActions && (
        <div className="ml-auto flex shrink-0 items-center gap-2">
          {actions?.play}
          {onSave && (
            <button
              aria-label={`Save ${title}`}
              className="rounded-full p-2 text-on-muted transition-colors hover:bg-black/20 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand"
              type="button"
              onClick={(event) => {
                event.stopPropagation();
                onSave();
              }}
            >
              <Heart aria-hidden="true" size={18} />
            </button>
          )}
          {actions?.save}
          {actionButtons}
        </div>
      )}
    </div>
  );
});

export default AudioCard;

'use client';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Play, ListPlus, Heart, Share2, User } from 'lucide-react';

export interface Track {
  id: string | number;
  title: string;
  artist?: string;
  artistId?: string | number;
  album?: string;
  coverUrl?: string;
  [key: string]: unknown;
}

export interface TrackContextMenuProps {
  children: React.ReactNode;
  track: Track;
  onPlayNext?: (track: Track) => void;
  onAddToQueue?: (track: Track) => void;
  onSaveToCollection?: (track: Track) => void;
  onShare?: (track: Track) => void;
  onViewArtist?: (track: Track) => void;
  className?: string;
  disabled?: boolean;
}

export function TrackContextMenu({
  children,
  track,
  onPlayNext,
  onAddToQueue,
  onSaveToCollection,
  onShare,
  onViewArtist,
  className = '',
  disabled = false,
}: TrackContextMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [focusedIndex, setFocusedIndex] = useState(0);

  const containerRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const longPressTimerRef = useRef<NodeJS.Timeout | null>(null);
  const touchStartPosRef = useRef<{ x: number; y: number } | null>(null);

  const menuItems = [
    {
      id: 'play-next',
      label: 'Play Next',
      icon: <Play size={16} />,
      action: () => onPlayNext?.(track),
    },
    {
      id: 'add-queue',
      label: 'Add to Queue',
      icon: <ListPlus size={16} />,
      action: () => onAddToQueue?.(track),
    },
    {
      id: 'save-collection',
      label: 'Save to Collection',
      icon: <Heart size={16} />,
      action: () => onSaveToCollection?.(track),
    },
    {
      id: 'share',
      label: 'Share',
      icon: <Share2 size={16} />,
      action: () => onShare?.(track),
    },
    {
      id: 'view-artist',
      label: 'View Artist',
      icon: <User size={16} />,
      action: () => onViewArtist?.(track),
    },
  ];

  const closeMenu = useCallback(() => {
    setIsOpen(false);
    setFocusedIndex(0);
  }, []);

  const openMenu = useCallback(
    (clientX: number, clientY: number) => {
      if (disabled) return;

      // Temporary raw position
      let x = clientX;
      let y = clientY;

      // Initial boundary check estimate
      const estimatedWidth = 200;
      const estimatedHeight = 220;
      const winWidth = typeof window !== 'undefined' ? window.innerWidth : 1000;
      const winHeight = typeof window !== 'undefined' ? window.innerHeight : 1000;

      if (x + estimatedWidth > winWidth - 10) {
        x = winWidth - estimatedWidth - 10;
      }
      if (y + estimatedHeight > winHeight - 10) {
        y = winHeight - estimatedHeight - 10;
      }

      setPosition({ x: Math.max(10, x), y: Math.max(10, y) });
      setFocusedIndex(0);
      setIsOpen(true);
    },
    [disabled]
  );

  // Desktop right-click context menu
  const handleContextMenu = (e: React.MouseEvent) => {
    if (disabled) return;
    e.preventDefault();
    e.stopPropagation();
    openMenu(e.clientX, e.clientY);
  };

  // Mobile long-press handling (500ms)
  const handleTouchStart = (e: React.TouchEvent) => {
    if (disabled || e.touches.length !== 1) return;
    const touch = e.touches[0];
    touchStartPosRef.current = { x: touch.clientX, y: touch.clientY };

    if (longPressTimerRef.current) {
      clearTimeout(longPressTimerRef.current);
    }

    longPressTimerRef.current = setTimeout(() => {
      openMenu(touch.clientX, touch.clientY);
      // Optional haptic feedback
      if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
        try {
          navigator.vibrate(50);
        } catch (_) {}
      }
    }, 500);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!longPressTimerRef.current || !touchStartPosRef.current) return;
    const touch = e.touches[0];
    const dx = Math.abs(touch.clientX - touchStartPosRef.current.x);
    const dy = Math.abs(touch.clientY - touchStartPosRef.current.y);

    // Cancel long press if scrolled/moved > 10px
    if (dx > 10 || dy > 10) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  };

  const handleTouchEnd = () => {
    if (longPressTimerRef.current) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  };

  // Adjust exact position after mounting menu based on actual bounds
  useEffect(() => {
    if (!isOpen || !menuRef.current) return;

    const rect = menuRef.current.getBoundingClientRect();
    const winWidth = window.innerWidth;
    const winHeight = window.innerHeight;

    setPosition((prev) => {
      let { x, y } = prev;
      if (x + rect.width > winWidth - 10) {
        x = winWidth - rect.width - 10;
      }
      if (y + rect.height > winHeight - 10) {
        y = winHeight - rect.height - 10;
      }
      return { x: Math.max(10, x), y: Math.max(10, y) };
    });

    // Focus the first item inside menu
    if (itemRefs.current[0]) {
      itemRefs.current[0]?.focus();
    }
  }, [isOpen]);

  // Focus trap and index sync
  useEffect(() => {
    if (isOpen && itemRefs.current[focusedIndex]) {
      itemRefs.current[focusedIndex]?.focus();
    }
  }, [isOpen, focusedIndex]);

  // Outside click & Escape & Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const handlePointerDownOutside = (e: PointerEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        closeMenu();
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return;

      if (e.key === 'Escape') {
        e.preventDefault();
        closeMenu();
        return;
      }

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setFocusedIndex((prev) => (prev + 1) % menuItems.length);
        return;
      }

      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setFocusedIndex((prev) => (prev - 1 + menuItems.length) % menuItems.length);
        return;
      }

      if (e.key === 'Home') {
        e.preventDefault();
        setFocusedIndex(0);
        return;
      }

      if (e.key === 'End') {
        e.preventDefault();
        setFocusedIndex(menuItems.length - 1);
        return;
      }

      if (e.key === 'Tab') {
        e.preventDefault(); // Focus trap: cycle inside menu
        if (e.shiftKey) {
          setFocusedIndex((prev) => (prev - 1 + menuItems.length) % menuItems.length);
        } else {
          setFocusedIndex((prev) => (prev + 1) % menuItems.length);
        }
      }
    };

    window.addEventListener('pointerdown', handlePointerDownOutside);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('pointerdown', handlePointerDownOutside);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, closeMenu, menuItems.length]);

  const handleSelect = (item: typeof menuItems[number]) => {
    item.action();
    closeMenu();
  };

  return (
    <div
      ref={containerRef}
      className={`relative inline-block ${className}`}
      onContextMenu={handleContextMenu}
      onTouchCancel={handleTouchEnd}
      onTouchEnd={handleTouchEnd}
      onTouchMove={handleTouchMove}
      onTouchStart={handleTouchStart}
    >
      {children}

      {isOpen && (
        <div
          ref={menuRef}
          aria-label={`Options for ${track.title}`}
          aria-orientation="vertical"
          className="w-52 py-1.5 rounded-xl bg-surface/95 backdrop-blur-md border border-border-dark shadow-2xl text-white outline-none focus:outline-none animate-in fade-in zoom-in-95 duration-100"
          role="menu"
          style={{
            position: 'fixed',
            top: `${position.y}px`,
            left: `${position.x}px`,
            zIndex: 9999,
          }}
        >
          <div className="px-3 py-1.5 mb-1 border-b border-border-dark/60 text-xs font-semibold text-on-muted truncate">
            {track.title}
          </div>

          {menuItems.map((item, index) => (
            <button
              key={item.id}
              ref={(el) => {
                itemRefs.current[index] = el;
              }}
              className={`w-full flex items-center gap-3 px-3 py-2 text-xs font-medium transition-colors text-left focus:outline-none ${
                focusedIndex === index
                  ? 'bg-brand text-white font-semibold'
                  : 'text-gray-200 hover:bg-surface-hover hover:text-white'
              }`}
              role="menuitem"
              tabIndex={focusedIndex === index ? 0 : -1}
              onClick={() => handleSelect(item)}
              onMouseEnter={() => setFocusedIndex(index)}
            >
              <span className="shrink-0 text-current">{item.icon}</span>
              <span className="truncate">{item.label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export default TrackContextMenu;

'use client';

import React, { useRef, useEffect, useState, useCallback, useMemo } from 'react';

export interface WaveformDisplayProps {
  /** Array of normalized amplitude values between 0 and 1 */
  data?: number[];
  /** Current playback position in seconds */
  currentTime?: number;
  /** Total duration in seconds */
  duration?: number;
  /** Direct progress fraction between 0 and 1 */
  progress?: number;
  /** Callback fired when user seeks */
  onSeek?: (progress: number, seekTime?: number) => void;
  /** Accent color for played portion of waveform */
  playedColor?: string;
  /** Color for unplayed portion of waveform */
  unplayedColor?: string;
  /** Color of playhead position line */
  playheadColor?: string;
  /** Desired height in pixels (min 60, max 200, default 80) */
  height?: number;
  /** Width of each bar in pixels */
  barWidth?: number;
  /** Gap between bars in pixels */
  barGap?: number;
  /** Additional CSS class names */
  className?: string;
  /** Enable seek interaction (default true) */
  interactive?: boolean;
}

// Generate fallback synthetic waveform data if none provided
function generateFallbackData(count: number = 80): number[] {
  const data: number[] = [];
  for (let i = 0; i < count; i++) {
    const sin1 = Math.sin((i / count) * Math.PI * 4);
    const sin2 = Math.cos((i / count) * Math.PI * 8);
    const val = 0.25 + 0.35 * Math.abs(sin1) + 0.35 * Math.abs(sin2 * 0.5);
    data.push(Math.min(1, Math.max(0.1, val)));
  }
  return data;
}

export function WaveformDisplay({
  data,
  currentTime,
  duration,
  progress,
  onSeek,
  playedColor = '#885FA8',
  unplayedColor = 'rgba(255, 255, 255, 0.2)',
  playheadColor = '#FFFFFF',
  height = 80,
  barWidth = 3,
  barGap = 2,
  className = '',
  interactive = true,
}: WaveformDisplayProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const isDraggingRef = useRef(false);

  // Clamp height between 60px and 200px
  const clampedHeight = useMemo(
    () => Math.max(60, Math.min(200, height)),
    [height]
  );

  // Determine actual waveform progress fraction [0, 1]
  const currentProgress = useMemo(() => {
    if (typeof progress === 'number') {
      return Math.max(0, Math.min(1, progress));
    }
    if (typeof currentTime === 'number' && typeof duration === 'number' && duration > 0) {
      return Math.max(0, Math.min(1, currentTime / duration));
    }
    return 0;
  }, [progress, currentTime, duration]);

  const rawAmplitudes = useMemo(() => {
    if (data && data.length > 0) return data;
    return generateFallbackData(80);
  }, [data]);

  const drawWaveform = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const rect = container.getBoundingClientRect();
    const width = rect.width;
    const heightPx = clampedHeight;

    if (width === 0) return;

    const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1;

    canvas.width = width * dpr;
    canvas.height = heightPx * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${heightPx}px`;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, width, heightPx);

    const slotWidth = barWidth + barGap;
    const numBars = Math.max(1, Math.floor((width + barGap) / slotWidth));

    // Resample amplitude data to match numBars
    const sampledAmplitudes: number[] = new Array(numBars);
    for (let i = 0; i < numBars; i++) {
      const startIdx = Math.floor((i / numBars) * rawAmplitudes.length);
      const endIdx = Math.max(startIdx + 1, Math.floor(((i + 1) / numBars) * rawAmplitudes.length));
      let sum = 0;
      let count = 0;
      for (let j = startIdx; j < endIdx && j < rawAmplitudes.length; j++) {
        sum += rawAmplitudes[j];
        count++;
      }
      sampledAmplitudes[i] = count > 0 ? sum / count : 0.1;
    }

    const playheadX = currentProgress * width;

    // Draw bars
    for (let i = 0; i < numBars; i++) {
      const x = i * slotWidth;
      const amp = sampledAmplitudes[i];
      const minBarHeight = 4;
      const maxBarHeight = heightPx - 12;
      const bHeight = Math.max(minBarHeight, amp * maxBarHeight);
      const y = (heightPx - bHeight) / 2;

      const barCenterX = x + barWidth / 2;
      const isPlayed = barCenterX <= playheadX;

      ctx.fillStyle = isPlayed ? playedColor : unplayedColor;

      // Draw rounded rectangle bar
      const radius = Math.min(barWidth / 2, bHeight / 2);
      ctx.beginPath();
      if (typeof ctx.roundRect === 'function') {
        ctx.roundRect(x, y, barWidth, bHeight, radius);
      } else {
        ctx.rect(x, y, barWidth, bHeight);
      }
      ctx.fill();
    }

    // Draw playhead vertical line
    ctx.beginPath();
    ctx.strokeStyle = playheadColor;
    ctx.lineWidth = 2;
    ctx.moveTo(playheadX, 0);
    ctx.lineTo(playheadX, heightPx);
    ctx.stroke();

    // Draw playhead top/bottom caps
    ctx.fillStyle = playheadColor;
    ctx.beginPath();
    ctx.arc(playheadX, 3, 3, 0, Math.PI * 2);
    ctx.arc(playheadX, heightPx - 3, 3, 0, Math.PI * 2);
    ctx.fill();
  }, [clampedHeight, barWidth, barGap, rawAmplitudes, currentProgress, playedColor, unplayedColor, playheadColor]);

  // Handle ResizeObserver & redraw
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let animationFrameId: number;

    const handleResize = () => {
      animationFrameId = requestAnimationFrame(drawWaveform);
    };

    const resizeObserver = new ResizeObserver(handleResize);
    resizeObserver.observe(container);
    window.addEventListener('resize', handleResize);

    drawWaveform();

    return () => {
      cancelAnimationFrame(animationFrameId);
      resizeObserver.disconnect();
      window.removeEventListener('resize', handleResize);
    };
  }, [drawWaveform]);

  // Handle Seeking
  const calculateSeekProgress = (clientX: number): number => {
    const container = containerRef.current;
    if (!container) return 0;
    const rect = container.getBoundingClientRect();
    if (rect.width === 0) return 0;
    const relX = clientX - rect.left;
    return Math.max(0, Math.min(1, relX / rect.width));
  };

  const triggerSeek = (newProgress: number) => {
    if (!onSeek) return;
    const seekTime = typeof duration === 'number' ? newProgress * duration : undefined;
    onSeek(newProgress, seekTime);
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive) return;
    isDraggingRef.current = true;
    (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
    const newProgress = calculateSeekProgress(e.clientX);
    triggerSeek(newProgress);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || !isDraggingRef.current) return;
    const newProgress = calculateSeekProgress(e.clientX);
    triggerSeek(newProgress);
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!interactive || !isDraggingRef.current) return;
    isDraggingRef.current = false;
    (e.target as HTMLElement).releasePointerCapture?.(e.pointerId);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!interactive || !onSeek) return;
    const step = 0.05; // 5% seek
    let newProgress = currentProgress;

    if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
      e.preventDefault();
      newProgress = Math.max(0, currentProgress - step);
    } else if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
      e.preventDefault();
      newProgress = Math.min(1, currentProgress + step);
    } else if (e.key === 'Home') {
      e.preventDefault();
      newProgress = 0;
    } else if (e.key === 'End') {
      e.preventDefault();
      newProgress = 1;
    } else {
      return;
    }

    triggerSeek(newProgress);
  };

  const formattedTime = typeof currentTime === 'number'
    ? `${Math.floor(currentTime / 60)}:${Math.floor(currentTime % 60).toString().padStart(2, '0')}`
    : `${Math.round(currentProgress * 100)}%`;

  return (
    <div
      ref={containerRef}
      aria-label="Audio waveform playback position"
      aria-valuemax={duration ?? 100}
      aria-valuemin={0}
      aria-valuenow={typeof currentTime === 'number' ? Math.round(currentTime) : Math.round(currentProgress * 100)}
      aria-valuetext={`Playback position ${formattedTime}`}
      className={`relative w-full rounded-xl bg-surface p-3 overflow-hidden select-none focus:outline-none focus:ring-2 focus:ring-brand ${
        interactive ? 'cursor-pointer' : ''
      } ${className}`}
      role={interactive ? 'slider' : 'img'}
      style={{
        minHeight: '60px',
        maxHeight: '200px',
        height: `${clampedHeight}px`,
      }}
      tabIndex={interactive ? 0 : -1}
      onKeyDown={handleKeyDown}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
    >
      <canvas ref={canvasRef} className="block w-full h-full" />
    </div>
  );
}

