            </div>

            <div className="flex flex-col gap-4 px-6 py-6">
              {navLinks.map(({ name, href }) => (
                <motion.div key={href} variants={itemVariants}>
                  <Link
                    className={`block text-base ${linkClass(href)}`}
                    href={href}
                    onClick={() => setIsMenuOpen(false)}
                  >
                    {name}
